import{_ as a,C as n,o as i,c as s,E as r,a2 as o}from"./chunks/framework.Cm6XCzck.js";const c="/joinwell52/assets/figures/2026-09-01-decision-evidence-continuity.en.png",g=JSON.parse('{"title":"You Have Fact Checks, Diagnostics, and EVAL. What Still Connects an Interrupted Task Takeover?","description":"","frontmatter":{"title":"You Have Fact Checks, Diagnostics, and EVAL. What Still Connects an Interrupted Task Takeover?","date":"2026-09-01","updated":"2026-09-02","column":"open-source-engineering","category":"daily","article_type":"comparative-engineering-analysis","research_question":"How can an interrupted same-TASK takeover link current authority, fact checks, diagnostics, and EVAL observation without granting any observer extra power?","evidence_status":"Research complete; contract frozen; implementation and independent QA not claimed","publication_authorized":true,"edition":"research-center","summary":"57 existing tests support four correctly separated capabilities, not a completed takeover evidence chain. Stable case identity links the prior attempt, effect facts, current authority, and disposition while keeping observation references and raw-text access bounded.","sources":"/en/research/evidence/2026-09-01-interruption-research","project_relevance":"substantive-relationship","item_id":"RIR-20260901-02","lifecycle":"Published","cover":"/assets/covers/daily-2026-09-01-decision-evidence-continuity-cover.png","citation_status":"Completed","editing_status":"Completed"},"headers":[],"relativePath":"en/engineering/2026-09-01-decision-evidence-continuity.md","filePath":"en/engineering/2026-09-01-decision-evidence-continuity.md","lastUpdated":1788322453000}'),d={name:"en/engineering/2026-09-01-decision-evidence-continuity.md"};function l(p,e,h,u,m,v){const t=n("ArticleCover");return i(),s("div",null,[r(t,{image:"/assets/covers/daily-2026-09-01-decision-evidence-continuity-cover.png",kicker:"Interruption research · 02",title:"Fact Checks, Diagnostics, and EVAL Exist. What Still Connects Takeover?",summary:"57 existing tests support four correctly separated capabilities, not a completed takeover evidence chain. Stable case identity links the prior attempt, effect facts, current authority, and disposition while keeping observation references and raw-text access bounded.",version:"RIR-20260901-02",status:"Engineering research · contract frozen",languageHref:"/zh/engineering/2026-09-01-decision-evidence-continuity",languageLabel:"中文"}),e[0]||(e[0]=o(`<h1 id="you-have-fact-checks-diagnostics-and-eval-what-still-connects-an-interrupted-task-takeover" tabindex="-1">You Have Fact Checks, Diagnostics, and EVAL. What Still Connects an Interrupted Task Takeover? <a class="header-anchor" href="#you-have-fact-checks-diagnostics-and-eval-what-still-connects-an-interrupted-task-takeover" aria-label="Permalink to &quot;You Have Fact Checks, Diagnostics, and EVAL. What Still Connects an Interrupted Task Takeover?&quot;">​</a></h1><p>An interrupted Runtime task can appear information-rich: a TASK file, Session and lease records, fact checking, diagnostic panels, and EVAL observation reports already exist.</p><p>Yet a successor Agent may still be unable to answer a simple question: <strong>which current decision admits this disposition?</strong></p><p>Putting every log on one page does not create authority. Giving EVAL a detailed observation report must not give it dispatch power. The missing piece is not another report. It is a constrained decision-evidence chain that connects an interrupted attempt, effect facts, current authority, and the successor Session while keeping fact checking, diagnostics, and EVAL inside their own boundaries.</p><p>CodeFlowMu is a local multi-Agent collaboration Runtime we develop. FCoP TASKs, REPORTs, and a five-bucket lifecycle organize engineering work. This article inspects real V2.1.2 modules and tests at commit <code>919c3b48</code>. The observations belong to that baseline; the subsequent takeover contract is frozen. This article describes its required connection, not a claim of implementation, independent-QA acceptance, or release.</p><h2 id="_1-two-external-reminders-inspectable-does-not-mean-allowed-to-continue" tabindex="-1">1. Two external reminders: inspectable does not mean allowed to continue <a class="header-anchor" href="#_1-two-external-reminders-inspectable-does-not-mean-allowed-to-continue" aria-label="Permalink to &quot;1. Two external reminders: inspectable does not mean allowed to continue&quot;">​</a></h2><p><a href="https://github.com/openai/codex" target="_blank" rel="noreferrer">OpenAI Codex</a> is OpenAI&#39;s open-source coding Agent. Its <a href="https://github.com/openai/codex/pull/41936" target="_blank" rel="noreferrer">#41936</a> retains bounded diagnostic evidence for Guardian failed reviews. Its lesson is not that more failure logs are always better; a failure decision itself needs a queryable record with defined limits.</p><p><a href="https://github.com/paperclipai/paperclip" target="_blank" rel="noreferrer">Paperclip</a> is an open-source multi-Agent team-management platform. Its <a href="https://github.com/paperclipai/paperclip/pull/12616" target="_blank" rel="noreferrer">#12616</a> was merged on 2026-09-01 and retains a default-off experimental design that proposes binding a native run to company, issue, run, coordinator, receipt, idempotency, and result fencing. It makes run provenance and receipt binding worth studying. Merged and default-off does not mean universally enabled, nor is this runner design an architecture to transplant into CodeFlowMu recovery.</p><p>Together they raise a narrow question: a recovered action should explain its decision source, but <strong>the existence of an old decision does not prove that a new action remains authorized.</strong></p><h2 id="_2-codeflowmu-already-has-four-correctly-separated-capabilities" tabindex="-1">2. CodeFlowMu already has four correctly separated capabilities <a class="header-anchor" href="#_2-codeflowmu-already-has-four-correctly-separated-capabilities" aria-label="Permalink to &quot;2. CodeFlowMu already has four correctly separated capabilities&quot;">​</a></h2><p>We ran 57 related tests over technical recovery, fact checking, EVAL, and evidence association: <code>57 pass / 0 fail / 0 skipped</code>. This is not a composite reliability score. Each set belongs to a different layer and proves only that layer’s role.</p><table tabindex="0"><thead><tr><th>Layer</th><th>What current evidence establishes</th><th>What it deliberately does not do</th></tr></thead><tbody><tr><td>Technical takeover</td><td><code>recoverTaskExecution</code> checks a <code>technical_recover</code> governance snapshot, revalidates revision, uses a recovery fence, and stops before wake if a live Session or changed revision appears</td><td>It does not infer that an effect occurred, or convert historical authority into a new re-execution grant</td></tr><tr><td>Fact checking</td><td><code>FactCheckDecisionService</code> records reasoned, idempotent PM/ADMIN decisions on a REVIEW; hard identity, authorization, and integrity violations cannot be overridden as evidence exceptions</td><td>It does not move TASK/ISSUE/lifecycle files or wake an Agent</td></tr><tr><td>EVAL</td><td>It emits internal observation/evidence bundles; tests show it does not create a TASK or move lifecycle, and its records have <code>drives_lifecycle=false</code></td><td>It does not make a business decision or become an authorization source</td></tr><tr><td>Evidence association</td><td>It links task, attempt, action, report, and review with stable keys; diagnostic caches are rebuildable and do not mutate lifecycle facts</td><td>A successful link does not authorize an action</td></tr></tbody></table><p>This separation is a strength. FCoP fact checking answers whether evidence and contracts stand. EVAL observes and identifies gaps. Diagnostics explain correlation conflicts. PM/ADMIN retains business decisions, and the Runtime retains technical wake.</p><p>A separate controlled probe adds a concrete contrast. An authorization-receipt marker supplied in Session context was absent from the persisted record, while denial remained <code>OPERATION_BOUNDARY_DENIED</code>. A synthetic error marker with an 8192-byte tail remained in the internal terminal event, yet Web Panel, Activity API, and Analytics projections all omitted it while retaining failure code and status. The former exposes a generic Session reference gap; the latter demonstrates an existing ordinary-consumer boundary. They must not be collapsed into “no audit,” or added to the 57 tests as a reliability score. See the <a href="/joinwell52/en/research/evidence/2026-09-01-interruption-research">preserved observations and fixture</a>.</p><h2 id="_3-the-break-the-four-capabilities-have-no-common-interruption-case" tabindex="-1">3. The break: the four capabilities have no common interruption case <a class="header-anchor" href="#_3-the-break-the-four-capabilities-have-no-common-interruption-case" aria-label="Permalink to &quot;3. The break: the four capabilities have no common interruption case&quot;">​</a></h2><p>The technical takeover path currently reads governance snapshots, attempts/leases, revisions, and wake conditions. It does not yet form a takeover record that can stably cite current authority, a fact-check result where one exists, and relevant observation evidence. The missing connection is not to put EVAL or diagnostics into dispatch; it is to let a takeover cite those materials when relevant while preserving their read-only boundaries.</p><p>The system can consequently answer many local questions correctly: whether the old Session is live; whether the lifecycle allows technical recovery; whether PM or ADMIN decided a REVIEW; whether EVAL found a reporting gap; and whether task, attempt, report, and review correlate by stable key.</p><p>It cannot yet produce one complete, traceable explanation for a takeover:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>original TASK (same bucket)</span></span>
<span class="line"><span>  → interrupted attempt and old lease</span></span>
<span class="line"><span>  → verified effect fact + current authority</span></span>
<span class="line"><span>  → takeover decision at the current revision (optional fact-check/diagnostic references)</span></span>
<span class="line"><span>  → successor Session or reconcile/hold disposition</span></span>
<span class="line"><span>  → EVAL observation and constrained query view</span></span></code></pre></div><p>This is not a shortage of prose, nor is it a problem with <code>task_id</code> identity. <strong>The same interruption takeover lacks a stable case identity and reference chain.</strong> The same TASK needs a referenceable interruption case so every record can establish that it concerns the same interruption, task round, and successor.</p><h2 id="_4-what-a-takeover-record-may-cite—and-what-it-must-never-authorize" tabindex="-1">4. What a takeover record may cite—and what it must never authorize <a class="header-anchor" href="#_4-what-a-takeover-record-may-cite—and-what-it-must-never-authorize" aria-label="Permalink to &quot;4. What a takeover record may cite—and what it must never authorize&quot;">​</a></h2><p>CodeFlowMu already has reusable contract shapes. <code>TaskScopeGrant</code> and <code>TaskCommandReceipt</code> carry <code>task_id</code>, <code>root_task_id</code>, <code>thread_key</code>, <code>round_id</code>, <code>expected_revision</code>, <code>authorization_ref</code>, an idempotency key, and expiry. They describe current technical authority, not approval for a specific external operation. Source alignment further separates successor/wake-scoped <code>TaskScopeGrant</code> from <code>OperationApprovalService</code> or a qualified equivalent executor, which checks operation authority at the actual tool-call boundary without advance consumption. We did not establish that ordinary Session takeover consumes this full structure, so field presence cannot be presented as completed continuity.</p><p>Three concepts must remain separate:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>historical receipt</span></span>
<span class="line"><span>→ explains why the original execution occurred</span></span>
<span class="line"><span></span></span>
<span class="line"><span>current authority</span></span>
<span class="line"><span>→ establishes whether re-execution is permitted at the current revision/round</span></span>
<span class="line"><span></span></span>
<span class="line"><span>interruption case / admission record</span></span>
<span class="line"><span>→ records the facts, decisions, and evidence used for this takeover</span></span></code></pre></div><p>The frozen contract does not create a second authorization system. It requires a case with its own immutable identity. This is a reading summary, not the full schema:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>interruption_case</span></span>
<span class="line"><span>  = case_id + task_id + interrupted_task_revision</span></span>
<span class="line"><span>  + interrupted_attempt_id + prior owner/lease identity + interrupted_at</span></span>
<span class="line"><span></span></span>
<span class="line"><span>case references</span></span>
<span class="line"><span>  = evaluated_task_revision + current_authority_ref + effect_fact_ref</span></span>
<span class="line"><span>  + admission_result + disposition|null</span></span>
<span class="line"><span>  + decision_revision + supersedes_revision? + decided_at</span></span>
<span class="line"><span>  + fact_check_ref? + diagnosis_ref? + eval_observation_ref?</span></span>
<span class="line"><span>  + successor_session_id?</span></span></code></pre></div><p>Source alignment distinguishes two leases: <code>SessionLeaseStore</code> uses an owner Session and TTL without a stable <code>lease_id</code>; <code>DispatchAttemptStore.ExecutionLease</code> has its own lease ID. A case must not treat them as the same field. Nor should a case manufacture an observation artifact just to fill a field: optional references are recorded only when they actually participate in the case.</p><p>Four limits are essential:</p><ol><li><strong>A historical receipt explains origin only.</strong> It may explain why the TASK originally began, but cannot automatically authorize today’s external action.</li><li><strong>Current authority is necessary for <code>reexecute</code>, but not sufficient.</strong> It must bind the current revision and round; a verified effect-absent fact and valid successor ownership are also required. A confirmed or unknown effect must not manufacture re-execution authority.</li><li><strong>Observation artifacts may be cited but cannot execute.</strong> EVAL, diagnostics, and fact checks provide references, summaries, digests, state, and reason codes—not wake or dispatch capabilities.</li><li><strong>Raw text remains behind existing boundaries.</strong> Large context, private EVAL bodies, and raw diagnostic text stay out of ordinary association output and remain readable only through the existing authorized paths.</li></ol><p>That is decision-evidence continuity: not a receipt replacing business judgement, but each new judgement being traceable to the facts and current authority it used.</p><p><img src="`+c+'" alt="Fact Checks, Diagnostics, and EVAL Exist. What Still Connects Takeover?"></p><p><em>Figure 1. Decision-evidence references. Historical receipts explain origin; current authority and effect facts support admission. Fact checks, diagnostics, and EVAL provide references only when relevant, never dispatch power. Source: RUN-004&#39;s 57 existing tests and the frozen contract; dashed lines are optional references, not execution commands.</em></p><p><a href="/joinwell52/assets/figures/2026-09-01-decision-evidence-continuity.en.png">Open full-resolution figure</a></p><h2 id="_5-keep-the-two-studies-distinct-join-them-only-in-acceptance" tabindex="-1">5. Keep the two studies distinct; join them only in acceptance <a class="header-anchor" href="#_5-keep-the-two-studies-distinct-join-them-only-in-acceptance" aria-label="Permalink to &quot;5. Keep the two studies distinct; join them only in acceptance&quot;">​</a></h2><p>The interruption-admission study asks what happened to the original effect. This study asks how that fact and the takeover decision are correctly attributed. Combining them into a generic “recovery feature test” hides two different failures: a system can know the effect happened but lack current authority, or have authority while lacking evidence about the effect.</p><p>Joint acceptance must therefore cover at least these cases:</p><table tabindex="0"><thead><tr><th>Case</th><th>Required linkage</th><th>Prohibited result</th></tr></thead><tbody><tr><td>Effect absent, safe re-execution</td><td>successor can trace current grant/decision, original attempt, and fact basis</td><td>re-execution on an expired receipt or only a thread string</td></tr><tr><td>Effect confirmed</td><td>case cites reconciliation conclusion and evidence</td><td>waking a successor to repeat the action</td></tr><tr><td>Effect unknown</td><td>case cites the hold owner and constrained evidence</td><td>automatic execution merely because the session is <code>recoverable</code></td></tr><tr><td>Late old-owner settle</td><td>case retains diagnostics and rejects stale write</td><td>overwriting successor authority</td></tr><tr><td>EVAL/diagnostic finding</td><td>observation is citable and queryable</td><td>EVAL moving a bucket, diagnostics directly authorizing, or raw text leakage</td></tr></tbody></table><p>These are future implementation acceptance conditions, not end-to-end capabilities already passed by V2.1.2.</p><h2 id="_6-why-this-matters-more-than-another-recovery-agent" tabindex="-1">6. Why this matters more than another recovery Agent <a class="header-anchor" href="#_6-why-this-matters-more-than-another-recovery-agent" aria-label="Permalink to &quot;6. Why this matters more than another recovery Agent&quot;">​</a></h2><p>Adding an Agent that summarizes logs cannot solve evidence ownership, current authority, or raw-text boundaries by itself. It may summarize more fluently while mixing another attempt’s logs, evidence created only after the decision point, or an expired grant into the current takeover.</p><p>One implementation precondition is equally important: the decision-evidence chain cannot live only behind one Recover button. Every UI, API, or scheduler entrypoint handling a technical-interruption successor must converge on one recovery admission. Normal authorized rework, reassignment, and new-round retry are not interruption recovery; a server-side classifier distinguishes mixed-purpose entries from durable state. Otherwise, one complete evidence path can be bypassed by another route that ignores current authority and effect facts.</p><p>Provider capabilities can still be reused. A platform’s session state and tool receipts can become evidence inputs. CodeFlowMu need not rebuild Codex, AG2, or Paperclip session products; it needs to preserve clear, auditable boundaries between the FCoP TASK, five buckets, current authority, and business disposition.</p><p>The important result is therefore not “we lack an Agent platform feature.” It is this: <strong>four correctly separated components need one same-TASK, auditable, non-privileged interruption-takeover reference chain.</strong></p><p>The takeover contract is now frozen: historical receipts explain origin; current recovery authority is separate from applicable operation authority; EVAL and diagnostics remain optional references. <code>successor_started</code>, or <code>reconciled</code> backed by a controlled completion reference, may resolve the case without deleting history. <code>hold_for_review</code> and <code>not_admitted</code> leave it open. Persistence, concurrency, crash recovery, and formal IA/DC acceptance still require implementation and independent QA; the 57 existing tests cannot replace them.</p><p>Companion reading: <a href="./2026-09-01-interrupted-task-takeover">Interrupted same-TASK takeover</a> · <a href="/joinwell52/en/research/evidence/2026-09-01-interruption-research">Bilingual evidence notes</a>.</p>',45))])}const y=a(d,[["render",l]]);export{g as __pageData,y as default};
